# Ronde 18: navigators zonder Dune-echo's (Lijngravers), toestemming als systeemgruwel; superkoeien zonder toestemming (idempotent)
import sqlite3,shutil,os
if not os.path.exists('canon_backup_ronde18.db'): shutil.copy('canon.db','canon_backup_ronde18.db')
c=sqlite3.connect('canon.db');n=0
G=' Label: donker thema, gruwel en onrecht; geen seksuele inhoud. Harde grens: seksuele handelingen alleen met volwassenen (18+) die volledig kunnen begrijpen, kiezen en weigeren; geen minderjarigen, geen dieren.'
GK=' Label: donker thema: gedwongen, volwassenen. Geen seksuele inhoud met wie door middelen, mishandeling of vervorming niet meer kan begrijpen of reageren; dan alleen horror, uitbuiting zonder seks en gevolgen. Geen minderjarigen, geen dieren.'
def add(code,cat,ond,feit,reden,refs,**kw):
  global n
  if c.execute("select 1 from canon where code=?",(code,)).fetchone(): return
  cols=['categorie','onderwerp','feit','status','reden','hangt_samen_met','ronde','code','verwijst_naar']+list(kw)
  c.execute(f"insert into canon({','.join(cols)}) values({','.join('?'*len(cols))})",[cat,ond,feit,'voorlopig','Ronde 18: '+reden,refs,18,code,refs]+list(kw.values()));n+=1
def vervang(code,door):
  c.execute("update canon set status='voorlopig, vervangen', reden=reden||? where code=? and status='voorlopig'",(f' [Ronde 18: vervangen door {door}]',code))
L='Lichaam en vervorming'
# ---------- regels ----------
add('REGEL-toestemming-systeem','Genre','Het systeem draait op toestemming die niet meer kan worden gegeven',"Overspannend principe voor Lijngravers (navigators), superkoeien (KOE-), tempelfokkerij en de Orde: Velmara's macht rust op lichamen van volwassenen die ooit ja zeiden, of van wie gezegd wordt dat ze ja zeiden, en die later niet meer kunnen weigeren. De Orde noemt dat heiligheid, Varenne contract, Kaldra plicht, Kharvos krijgsrecht. In de canon is het een misdaad: elk 'ja' van vroeger wordt gebruikt om een 'nee' van nu onmogelijk te maken. Vier fictie-vormen: voorinstemming (gelofte/contract), gift (familie of huis 'geeft' iemand), verplichting (schuld, straf, krijgsrecht) en vervalsing (vervalste registers, afgedwongen handtekening, gedrogeerde ja). Schrijfregel: dit is horror en onrecht, nooit erotiek; seksuele inhoud alleen met wie op dat moment volledig vrij kan instemmen."+G,'overspannende toestemmingsregel','REGEL-harde-grenzen;REGEL-toestemming-navigators;LIJN-overzicht;KOE-toestemming;LICH-tempelfokkerij;ORDE-orde;HUI-varenne;HUI-kaldra;REG-kharvos')
add('REGEL-toestemming-navigators','Genre','Toestemming bij de Lijngravers',"Het toestemmingsvermogen verdwijnt per fase (zie LIJN-fase-1 t/m 5). Fase 1: volledig. Fase 2: begrip volledig, wil aangetast door de trek van de Zegel; seksuele rol alleen vrijwillig en met telkens nieuwe instemming, de partner stopt bij elke twijfel. Vanaf fase 3 geen geldige instemming meer en dus nooit een seksuele rol, ook niet op grond van een eerdere gelofte: voorinstemming geldt in de canon niet. Fase 4-5: alleen verzorging, horror, uitbuiting zonder seks en moreel-juridische gevolgen. Strenger dan ronde 17 (die fase 3 nog toeliet)."+G,'toestemmingsgrens navigators','REGEL-harde-grenzen;REGEL-toestemming-systeem;LIJN-overzicht')
# ---------- Lijngravers ----------
add('LIJN-overzicht',L,'Lijngravers (intern label: navigators)',"Naam: Lijngravers; officieel 'Gedragenen van Ysa', in de volksmond 'maden'. Oorzaak: de Zegel herkent zenuwweefsel van sterk ingeteelde lijnen (kleine bloedafstand) als zijn eigen; wie zo'n lijn draagt en lang op een zegellijn werkt, wordt door de Zegel ingeworteld. Mechaniek: de Zegel groeit als witte wortelvezels door hun zenuwen; zij voelen daardoor waar zegellijnen lopen, waar lekzones zijn en waar de Zegel scheurt; ze wijzen landroutes, kustroutes en lekken aan, geen reizen door ruimte of tijd, geen drug, geen vaten. Eindpunt: de Wortel, een mens die in een zegellijn vergroeit en daar langzaam door de Zegel wordt opgegeten en hem voedt. De gruwel: hoe beter ze navigeren, hoe minder ze nog kunnen kiezen. Dune-echo's verwijderd: geen spice of verslavend middel, geen tanks/tonnen, geen reuzenzandworm, geen ruimtevaart. Vervangt NAV-wormwording."+G,'eigen naam, oorzaak en mechaniek','FUNC-NAV;REGEL-toestemming-navigators;REGEL-verwantschapstaboe;LIJN-fase-1;LIJN-voorinstemming;LIJN-quest',functie='NAV;INFO',afstoting=9,aantrekking_bron='geen (gruwel)',aantrekking=0)
FA=[(1,'Bleking (0-2 jaar)','Huid wordt glad en wit, haar valt uit, vingertoppen tintelen bij zegellijnen.','Volledig: begrijpt, kiest en kan weigeren. Omkeerbaar: wie nu stopt en de zegellijnen verlaat, herstelt in een jaar.','Dit is de laatste echte keuze: de Drempel aan het eind van fase 1. Hier tekenen ze het contract of de gelofte.','Twijfel, trots, angst; sommigen voelen zich uitverkoren.',4,'gevoeligheid, ontzag (alleen bij vrije volwassenen)',2),
(2,'Ring (2-5 jaar)','Ringplooien over romp, botten zachter, benen vergroeien deels; witte vezels zichtbaar onder de huid.','Begrip volledig, maar de wil wordt getrokken: weg van een zegellijn voelt als verstikking. Ze kunnen nog nee zeggen, maar het kost alles. Onomkeerbaar.','Weigeren kan nog in woorden; de Orde en Varenne registreren elke weigering als "zegelkoorts" en negeren haar.','Spijt begint; ze weten wat er komt en zien het bij anderen.',6,'nauwelijks; alleen vrijwillige partners met telkens nieuwe instemming',1),
(3,'Kruip (5-9 jaar)','Armen worden stompen, lichaam strekt tot 2-3 meter, mond wordt rond; ogen bijna blind.','Begrip in vlagen: heldere uren tussen dagen van zegelgeruis. Ze zeggen ja of nee maar kunnen niet meer wegen of onthouden wat ze zeiden. Geen geldige instemming meer.','Het laatste nee: in heldere uren smeken velen om de dood of om terug; dat wordt niet opgeschreven.','Doodsangst, rouw om de eigen naam, soms verzet (bijten, zich losscheuren van de lijn).',8,'geen',0),
(4,'Blind (9-14 jaar)','Gezicht vergroeit, geen ogen, huid doorschijnend met witte vezels; kruipt langs de lijn.','Geen woorden, geen begrip van wat er gebeurt; alleen pijn, warmte en beelden die verzorgers via aanraking opvangen. Kan niet weigeren.','Niets meer te kiezen; wie het lichaam bezit, beslist alles.','Pijn en een gloeiend verlangen naar de lijn; of er nog een ik is weet niemand.',9,'geen',0),
(5,'Wortel (14+ jaar)','Vergroeit met de zegellijn in rots of grond tot een witte, ademende wortelknoop; wordt door de Zegel langzaam opgegeten.','Geen ik meer naar buiten; Vathren horen soms een stem in de wortel die om hulp vraagt.','Geen.','Onbekend; de stem in de wortel is het ergste geheim van de Orde.',10,'geen',0)]
for i,nm,lich,venster,keuze,innerlijk,af,ab,aa in FA:
  add(f'LIJN-fase-{i}',L,f'Lijngraver fase {i}: {nm}',f"Lichaam: {lich} Toestemmingsvenster: {venster} Laatste keuze in deze fase: {keuze} Innerlijk: {innerlijk} Afstoting {af}/10; aantrekking {aa}/5 ({ab}). Vervangt NAV-wormfase-{i}."+G,'fase met toestemmingsvenster','LIJN-overzicht;REGEL-toestemming-navigators',functie='NAV',afstoting=af,aantrekking_bron=ab,aantrekking=aa)
X=[('voorinstemming','De fictie van voorinstemming',"Vijf vormen: (1) Gelofte van de Orde: bij de Drempel zweert de lijnlezer zich aan Ysa 'tot de wortel'; de Orde houdt die eed voor eeuwig geldig. (2) Contract van Varenne: schulden worden kwijtgescholden in ruil voor het lichaam 'met alle fasen'; ondertekend door verarmde gaven-mannen. (3) Gift: families en huizen 'geven' een ingeteeld lid aan de Orde als eerbetoon; de betrokkene tekent niet zelf. (4) Verplichting: Kharvos legt krijgsgevangenen het lot op via krijgsrecht; Kaldra via strafrecht. (5) Vervalsing: registers waarin de Drempel-gelofte wordt bijgeschreven bij wie nooit zwoer, of een ja van iemand die al in fase 3 was. De canon: geen van deze vormen is geldig voorbij fase 2."),
('drukmiddelen','Drukmiddelen bij de Drempel','Schuld (familieschulden bij Varenne), geloof (de belofte van heiligheid en dat je moeder in de Zegel wacht), liefde (een partner of zuster die wordt gespaard als jij gaat), dwang (gevangenschap op een zegellijn tot fase 2 begint en terug onmogelijk is). Wie de laatste keuze afdwingt of vervalst: Drempelmoeders van de Orde, Varenne-schuldmeesters, Mirre-kapiteins (scheepseed), Kharvos-krijgsrechters.'),
('spijt','Spijt en weerstand','In fase 2 en de heldere uren van fase 3 schrijven Lijngravers krasbrieven in hun eigen huid, weigeren routes te wijzen of wijzen opzettelijk lekzones aan om hun dragers mee te sleuren; de Orde noemt dat lijnwaan en bestraft verzorgers die het doorgeven. Een geheim krasalfabet circuleert tussen graverkampen.'),
('hoeders','Hoeders: wie verzorgt of bezit',"Vervangt NAV-wormdienaressen. Hoeders (volwassen verzorgers, vaak schuldvrouwen of boetelingen) wassen, voeden en dragen Lijngravers. Gevolgen: schuld en rouw, slapeloosheid, het horen van de wortelstem; veel hoeders worden verzetslid. Eigenaren (Orde, Varenne, Mirre, Kharvos) bezitten het lichaam als goed; seksuele toegang tot Lijngravers vanaf fase 3 is in de canon een misdaad en wordt alleen als misdaad met gevolgen verteld, nooit als scène. Wie het toch doet wordt in de verhalen ontmaskerd als dader."),
('verzet','Verzet en vluchtroutes',"De Losmakers: een netwerk van hoeders, Stille Zusters en Vathren dat Lijngravers in fase 1-2 van de lijnen weghaalt (in fase 1 nog genezend) of in fase 3-5 een genadedood geeft. Vluchtroutes: de Grijswortel-paden door Groenmuil (ver van zegellijnen), Myrrhen-veenhallen waar de zwam de wortelvezels remt, Oevrin-slikgangen langs de kust, en de Ishvar-woestijn waar geen zegellijn loopt."),
('quest','Gevolgen voor de quest',"Liora's gloed trekt Lijngravers aan: een lijnlezer in fase 2 die haar volgt, smeekt haar in een helder moment om verlossing. Teo ontdekt bij zijn Wijding (801) dat zijn eigen ingeteelde lijn in het register al voor de Drempel is 'gegeven': hij is voorbestemd Lijngraver. Samen vinden ze een Wortel bij Ves-Anath die met de stem van een vrouw uit Liora's register praat; zo bewijzen ze dat het systeem mensen opeet die niet meer kunnen kiezen. De keuze voor de quest: de Wortels gebruiken om de weg naar Ves-Anath te vinden, of hen bevrijden en blind verder gaan.")]
for s,nm,f in X:
  add(f'LIJN-{s}',L,nm,f+G,'toestemming als systeemgruwel',f'LIJN-overzicht;REGEL-toestemming-navigators;REGEL-toestemming-systeem'+(';PER-liora;PER-gewone-mannen;PLEK-LICH-ves-anath' if s=='quest' else '')+(';VOLK-myrrhen;VOLK-oevrin;VOLK-ishvar;VOLK-vathren' if s=='verzet' else ''),functie='NAV;CTRL',afstoting=8,aantrekking_bron='geen (gruwel)',aantrekking=0)
J=[('orde','Rechtvaardiging van de Orde','"Wie zich aan Ysa gaf, kan zich niet terugnemen; de wortel is de hoogste heiligheid." Theologie van de onherroepelijke gelofte.','ORDE-orde'),
('varenne','Rechtvaardiging van Varenne','"Een contract is een contract; het lichaam is onderpand en wij hebben de schuld gedragen." Handelsrecht boven mensenrecht.','HUI-varenne'),
('mirre','Rechtvaardiging van Mirre','"Het schip leeft of sterft samen; de loods gaf zich aan het schip." Zoutloodsen groeien in de kiel van het schip in plaats van in vaten.','HUI-mirre'),
('kharvos','Rechtvaardiging van Kharvos','"Krijgsgevangenen hebben hun leven al verloren; zo betalen ze terug." Krijgsrecht als vergunning.','REG-kharvos')]
for s,nm,f,r in J:
  add(f'LIJN-recht-{s}',L,nm,f+' In de canon: een rechtvaardiging, geen recht; de verhalen tonen haar als leugen.'+G,'rechtvaardiging machthebbers',f'LIJN-voorinstemming;{r}')
P={'lijnlezer':('Orde','gelofte, vaak onder geloofsdruk; vervalst bij ingeteelde Dochters','NAV-lijnlezer'),'zaadkompas':('Varenne','schuldcontract, afgedwongen','NAV-zaadkompas'),'zoutloods':('Mirre','scheepseed; vergroeien in de kiel van het schip, niet in vaten','NAV-zoutloods'),'schaduwhonden':('Kharvos','krijgsrecht, gedwongen','NAV-schaduwhonden'),'hartstem':('niemand','vrijwillig in paren, maar vanaf fase 3 kunnen ze elkaar niet meer loslaten','NAV-hartstem')}
for t,(eig,vorm,oud) in P.items():
  add(f'LIJN-{t}-pad',L,f'Gravenpad van de {t}',f'Eigenaar: {eig}. Vorm van (voor)instemming: {vorm}. Volgt LIJN-fase-1 t/m 5; laatste echte keuze bij de Drempel (eind fase 1); vanaf fase 3 geen instemming en geen seksuele rol. Vervangt {oud}-wormpad en de verouderde delen van {oud} (dagelijkse afhankelijkheid/vaten vervallen).'+G,'wormpad herschreven',f'LIJN-overzicht;{oud};LIJN-voorinstemming',functie='NAV',afstoting=8,aantrekking_bron='geen (gruwel)',aantrekking=0)
  vervang(f'NAV-{t}-wormpad',f'LIJN-{t}-pad')
for i in range(1,6): vervang(f'NAV-wormfase-{i}',f'LIJN-fase-{i}')
vervang('NAV-wormwording','LIJN-overzicht');vervang('NAV-wormdienaressen','LIJN-hoeders')
for t in ('lijnlezer','zoutloods'): vervang(f'NAV-{t}',f'LIJN-{t}-pad')
c.execute("update canon set feit=feit||' [Ronde 18: alleen bij vrije volwassenen tot fase 2 van de Lijngravers; nooit bij wie niet meer kan instemmen.]' where code='VOOR-metamorfose' and feit not like '%Ronde 18%'")
# ---------- superkoeien ----------
add('KOE-toestemming','Lichaam en vervorming','Superkoeien en toestemming: overzicht',"Superkoeien zijn volwassen mannen die zich bewust zijn van wat er met hen gebeurt; hun zaad wordt gewonnen zonder geldige instemming. Middelen: dwang en gevangenschap (stallen, kragen, kettingen), schuld (verkochte familieschulden), geloof (de leer dat zaadgeven gebed is), afgedwongen of vervalste instemming (registers met een 'gelofte' die nooit werd uitgesproken) en drugs: Ankerwortel, het tegenmiddel van Grijswortel, dat de binding versterkt, het verlangen chemisch opwekt en de wil dempt; bij hoge doses verdwijnt het vermogen om te begrijpen en te reageren. Wanneer dat vermogen door mishandeling of middelen wegvalt, geldt: geen seksuele inhoud, alleen horror, uitbuiting en gevolgen. Rechtvaardigingen: de Orde (heilige plicht van het zaad), Varenne (eigendom door koop), Kaldra (oorlogsnood). Verzet: KOE-opstand, Grijswortel-smokkel, zwijgen en zelfverwonding."+GK,'superkoeien zonder toestemming','REGEL-toestemming-systeem;KOE-tempelstier;KOE-melkos;KOE-reuzenstier;KOE-legerstal;KOE-opstand;KOE-ankerwortel',functie='PROD;CTRL',afstoting=8,aantrekking_bron='geen (gruwel)',aantrekking=0)
add('KOE-ankerwortel','Magie','Ankerwortel (tegenmiddel van Grijswortel)','Een wortel uit de fokstallen die het tegenovergestelde van Grijswortel doet: de binding aan de stal wordt sterker, de zaadproductie hoger, de wil zwakker. Lage dosis: de man weet alles maar kan zich nauwelijks verzetten. Hoge dosis of jaren gebruik: hij begrijpt niet meer wat er gebeurt; toestemming is dan onmogelijk en elke zaadwinning is pure uitbuiting.'+GK,'drug van het stalsysteem','KOE-toestemming;LICH-tempelfokkerij',functie='CTRL;PROD',afstoting=6,aantrekking_bron='geen',aantrekking=0)
T=[('tempelstier','Orde','Geen vrijheid; officieel vrijwillige wijdingsgelofte, feitelijk vervalst of onder geloofsdruk afgelegd.','Weet wat hij geeft maar niet dat het de Zegel voedt; wil vaak geloven omdat het dragelijker is; verzet door te bidden om onvruchtbaarheid.','Vermogen tot instemmen valt weg na jaren Ankerwortel en vijf winningen per dag; dan alleen horror en uitbuiting zonder seks.'),
('melkos','Varenne en Ambergaardse stalvrouwen','Weinig vrijheid; schuldcontract van de familie, afgedwongen bij aankoop.','Weet alles, verlangt naar vrijheid, haat de melkkraag; Bram komt hieruit en draagt de schaamte en woede mee.','Bij gewone mannen blijft het begrip meestal intact; het systeem rekent op uitputting en schuld, niet op drugs.'),
('reuzenstier','Varenne (Zaadbeurs)','Geen vrijheid; als gift van het huis verkocht, nooit zelf gevraagd.','Spreekt en begrijpt, maar wordt behandeld als vee; pijn door groei; sommigen leren lezen en schrijven in het geheim.','Vermogen valt weg door pijnmiddelen en Ankerwortel in de laatste jaren voor hun dood rond 40.'),
('legerstal','Kaldra','Beperkte vrijheid; diensteed onder krijgsrecht, afgedwongen bij rekrutering.','Weet wat hij doet en waarom; sommigen trots, anderen gebroken door het gebruik voor elke Strijdontvangst.','Vermogen valt weg bij uitputting na veldtochten; Kaldra-artsen geven dan Ankerwortel.')]
for t,eig,vrij,innerlijk,wegval in T:
  add(f'KOE-{t}-toestemming','Lichaam en vervorming',f'Toestemming bij de {t}',f'Eigenaar: {eig}. Mate van vrijheid en toestemming: {vrij} Innerlijk (weten, willen, voelen, verzet): {innerlijk} Wanneer instemmen wegvalt: {wegval} Rechtvaardiging: zie KOE-toestemming.'+GK,'toestemming per koetype',f'KOE-{t};KOE-toestemming;KOE-ankerwortel',functie='PROD;CTRL',afstoting=7,aantrekking_bron='geen (gruwel)',aantrekking=0)
add('LICH-tempelfokkerij-toestemming','Lichaam en vervorming','Tempelfokkerij en toestemming','De tempelfokkerij koppelt mannen en vrouwen op register, niet op keuze; ingeteelde lijnen worden bewust gekoppeld voor sterkere gaven en Lijngraver-aanleg. Instemming wordt afgedwongen via geloof en Ankerwortel, of vervalst in het register. De kinderen komen niet in seksuele rollen; hun ingeteelde lijn maakt hen later voorbestemd tot Lijngraver: zo voedt het ene onrecht het volgende.'+GK,'tempelfokkerij in toestemmingssysteem','LICH-tempelfokkerij;REGEL-toestemming-systeem;LIJN-overzicht;KOE-ankerwortel',functie='VOORT;CTRL',afstoting=8,aantrekking_bron='geen (gruwel)',aantrekking=0)
# ---------- F ----------
W=[('WRIJ-077','Voorinstemming vs Orde-leer van vrije overgave','LIJN-voorinstemming; REGEL-seksuele-normen','De Orde preekt vrijwillige overgave maar houdt geloften geldig voorbij het vermogen om te kiezen: kern-hypocrisie.','bron van verhalen'),
('WRIJ-078','Fase 3 in ronde 17 vs ronde 18','NAV-wormfase-3; LIJN-fase-3','Ronde 17 liet seks in fase 3 toe; ronde 18 niet meer. Oude rij gemarkeerd vervangen.','mogelijke fout'),
('WRIJ-079','Ankerwortel en Grijswortel','KOE-ankerwortel; KOE-opstand','Als de Orde in 740 Grijswortel verbood, waar komt Ankerwortel vandaan en sinds wanneer?','bron van verhalen'),
('WRIJ-080','Stem in de Wortel','LIJN-fase-5; VOLK-vathren','Is de stem een overblijfsel van de mens of de Zegel zelf? Raakt de magietheorie.','bron van verhalen'),
('WRIJ-081','Teo voorbestemd Lijngraver','LIJN-quest; PER-gewone-mannen','Teo is een gewone man; ingeteelde aanleg vraagt een register-oorsprong die nog niet in de canon staat.','mogelijke fout')]
for code,t,d,b,ty in W:
  if not c.execute("select 1 from wrijving where code=?",(code,)).fetchone():
    c.execute("insert into wrijving(titel,delen_die_botsen,beschrijving,type,status,code,verwijst_naar) values(?,?,?,?,'open',?,?)",(t,d,b,ty,code,d.replace('; ',';')))
Q=[('VRAAG-048','Bevrijden of gebruiken Liora en Teo de Wortels op weg naar Ves-Anath?','Morele kernkeuze van de quest.','LIJN-quest'),
('VRAAG-049','Kan de Drempel (fase 1) in het verhaal worden teruggedraaid door de Myrrhen-zwam?','Hoop en vluchtroute.','LIJN-verzet;VOLK-myrrhen'),
('VRAAG-050','Weet het volk van Ankerwortel, of is het een stalgeheim?','Wie-weet-wat.','KOE-ankerwortel'),
('VRAAG-051','Is Lijngravers de definitieve naam?','Naamkeuze Rogier.','LIJN-overzicht')]
for code,v,w,r in Q:
  if not c.execute("select 1 from open_vraag where code=?",(code,)).fetchone():
    c.execute("insert into open_vraag(vraag,waarom_belangrijk,status,code,verwijst_naar) values(?,?,'open',?,?)",(v,w,code,r))
if not c.execute("select 1 from logboek where wat like 'Ronde 18:%'").fetchone():
  c.execute("insert into logboek(datum,wat) values('2026-10-30','Ronde 18: navigators herschreven tot Lijngravers zonder Dune-echo''s (eigen oorzaak: Zegel wortelt in ingeteeld zenuwweefsel), toestemmingsvenster per fase, fictie van voorinstemming, drukmiddelen, spijt, hoeders, verzet, rechtvaardigingen, quest; REGEL-toestemming-navigators en REGEL-toestemming-systeem; superkoeien en tempelfokkerij zonder toestemming met Ankerwortel; oude NAV-worm-rijen gemarkeerd vervangen.')")
c.commit();print('nieuw',n)
codes={r[0] for r in c.execute('select code from canon')}
print('ontbrekend',{x for (v,) in c.execute("select verwijst_naar from canon where ronde=18") for x in (v or '').split(';') if x and x not in codes})
